int shipWithinDays(int[] weights, int days) {
    int lo = 0, hi = 0;
    for (int w : weights) { lo = Math.max(lo, w); hi += w; }
    while (lo < hi) {
        int cap = lo + (hi - lo) / 2;
        int need = daysNeeded(weights, cap);
        if (need <= days) hi = cap;
        else lo = cap + 1;
    }
    return lo;
}

int daysNeeded(int[] weights, int cap) {
    int d = 1, load = 0;
    for (int w : weights) {
        if (load + w > cap) { d++; load = 0; }
        load += w;
    }
    return d;
}

